function update(dt) {
    if (phase !== 'playing') return;
    // Rotation
    const turn = (keys.has('ArrowRight') || keys.has('d') || keys.has('D') ? 1 : 0) -
                 (keys.has('ArrowLeft')  || keys.has('a') || keys.has('A') ? 1 : 0);
    const TURN_SPEED = Math.PI * 2; // rad per second
    player.angle += turn * TURN_SPEED * dt;
    // Acceleration
    const thrust = keys.has('ArrowUp') || keys.has('w') || keys.has('W');
    if (thrust) {
      player.vx += Math.cos(player.angle) * PLAYER_ACCEL * dt;
      player.vy += Math.sin(player.angle) * PLAYER_ACCEL * dt;
    }
    // Apply friction
    const decay = Math.pow(PLAYER_FRICTION, dt);
    player.vx *= decay;
    player.vy *= decay;
    // Clamp speed
    const speed = Math.hypot(player.vx, player.vy);
    if (speed > PLAYER_MAX_SPEED) {
      const scale = PLAYER_MAX_SPEED / speed;
      player.vx *= scale;
      player.vy *= scale;
    }
    // Update position with wrap
    player.x = (player.x + player.vx * dt + W) % W;
    player.y = (player.y + player.vy * dt + H) % H;
    player.visible = true;
  }

